package com.eventpulse.service;
import com.eventpulse.model.UserProfile; import com.eventpulse.repository.UserRepository; import java.util.*; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class UserServiceTest {
 @Test void createsProfileWithVerifiedCognitoEmail(){var repo=mock(UserRepository.class);when(repo.findById("sub-1")).thenReturn(Optional.empty());when(repo.save(any())).thenAnswer(i->i.getArgument(0));var profile=new UserService(repo).get("sub-1","verified@example.test","User",false);assertEquals("sub-1",profile.getUserId());assertEquals("verified@example.test",profile.getEmail());assertEquals("USER",profile.getRole());verify(repo).save(profile);}
 @Test void repairsExistingProfileWithBlankEmail(){var repo=mock(UserRepository.class);var existing=new UserProfile();existing.setUserId("sub-1");existing.setEmail(" ");when(repo.findById("sub-1")).thenReturn(Optional.of(existing));when(repo.save(any())).thenAnswer(i->i.getArgument(0));var profile=new UserService(repo).get("sub-1","verified@example.test","User",false);assertEquals("verified@example.test",profile.getEmail());verify(repo).save(profile);}
 @Test void doesNotOverwriteValidEmailWhenCognitoEmailIsMissing(){var repo=mock(UserRepository.class);var existing=new UserProfile();existing.setUserId("sub-1");existing.setEmail("existing@example.test");when(repo.findById("sub-1")).thenReturn(Optional.of(existing));when(repo.save(any())).thenAnswer(i->i.getArgument(0));var profile=new UserService(repo).get("sub-1"," ",null,false);assertEquals("existing@example.test",profile.getEmail());verify(repo).save(profile);}
 @Test void createsTestUserProfileOnFirstLookup(){var repo=mock(UserRepository.class);when(repo.findById("test-user")).thenReturn(Optional.empty());when(repo.save(any())).thenAnswer(i->i.getArgument(0));UserProfile u=new UserService(repo).get("test-user");assertEquals("test-user",u.getUserId());assertEquals("USER",u.getRole());verify(repo).save(u);}
}
